export const KEY_MAX_LENGTH = 4;

/**
 * Derives a project key from `base` that collides with nothing in `taken`, by
 * appending 2, 3, … — the same scheme `uniqueSlug` uses for addresses — while
 * keeping the result within `KEY_MAX_LENGTH` characters.
 */
export function uniqueKey(
  base: string,
  taken: Iterable<string>,
  maxLength = KEY_MAX_LENGTH,
): string {
  const used = new Set(taken);
  const candidateBase = base.slice(0, maxLength).toUpperCase() || "TASK".slice(0, maxLength);
  if (!used.has(candidateBase)) return candidateBase;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const suffixStr = String(suffix);
    const candidate = `${candidateBase.slice(0, maxLength - suffixStr.length)}${suffixStr}`;
    if (!used.has(candidate)) return candidate;
  }
  throw new InvalidSlugError(candidateBase, "exhausted unique suffixes");
}

